<script setup>
import { onMounted, ref, watch } from 'vue';import { Plus, Search, Check, X, KeyRound, Pencil } from '@lucide/vue'
import { api } from '../../services/api';import { money } from '../../utils';import { uiStore } from '../../stores/ui'
import PageHeader from '../../components/PageHeader.vue';import LoadingBlock from '../../components/LoadingBlock.vue';import EmptyState from '../../components/EmptyState.vue';import EntityAvatar from '../../components/EntityAvatar.vue';import StatusBadge from '../../components/StatusBadge.vue';import BaseModal from '../../components/BaseModal.vue';import PaginationBar from '../../components/PaginationBar.vue'
const rows=ref([]),loading=ref(true),meta=ref({page:1,limit:20,total:0}),filters=ref({search:'',status:''}),modal=ref(''),busy=ref(false),selected=ref(null),form=ref({code:'',name:'',short_name:'',logo_url:'',registration_status:'APPROVED',is_active:true,username:'',password:''});let debounce
async function load(page=1){loading.value=true;try{const r=await api.get('/clubs',{page,limit:20,...filters.value});rows.value=r.data;meta.value=r.meta}catch(e){uiStore.notify(e.message,'error')}finally{loading.value=false}}
watch(filters,()=>{clearTimeout(debounce);debounce=setTimeout(()=>load(1),300)},{deep:true});onMounted(()=>load())
function openCreate(){selected.value=null;form.value={code:'',name:'',short_name:'',logo_url:'',registration_status:'APPROVED',is_active:true,username:'',password:''};modal.value='club'}
function openAccount(row){selected.value=row;form.value={username:row.username||'',password:'',is_active:Boolean(row.account_active)};modal.value='account'}
async function saveClub(){busy.value=true;try{await api.post('/clubs',form.value);uiStore.notify('Đã tạo câu lạc bộ.');modal.value='';load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function approve(row,status){try{await api.post(`/clubs/${row.id}/approval`,{status});uiStore.notify(status==='APPROVED'?'Đã duyệt CLB.':'Đã cập nhật trạng thái.');load(meta.value.page)}catch(e){uiStore.notify(e.message,'error')}}
async function saveAccount(){busy.value=true;try{await api.put(`/clubs/${selected.value.id}/account`,form.value);uiStore.notify('Đã cập nhật tài khoản CLB.');modal.value='';load(meta.value.page)}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
</script>
<template><div><PageHeader eyebrow="Club Management" title="Quản lý câu lạc bộ" description="Duyệt đăng ký, quản lý một tài khoản chung cho mỗi CLB và theo dõi ví tài chính."><button class="btn btn-primary" @click="openCreate"><Plus :size="17"/>Tạo CLB</button></PageHeader><div class="glass card toolbar"><div class="toolbar-actions"><div class="search"><Search :size="17"/><input v-model="filters.search" class="input" placeholder="Tìm CLB..."/></div><select v-model="filters.status" class="select"><option value="">Tất cả trạng thái</option><option value="PENDING">Chờ duyệt</option><option value="APPROVED">Đã duyệt</option><option value="REJECTED">Từ chối</option><option value="SUSPENDED">Tạm khóa</option></select></div><span class="muted">{{ meta.total }} CLB</span></div><LoadingBlock v-if="loading"/><EmptyState v-else-if="!rows.length"/><div v-else class="glass card table-card"><div class="table-wrap"><table><thead><tr><th>CLB</th><th>Trạng thái</th><th>Cầu thủ</th><th>Số dư</th><th>Tài khoản</th><th>Thao tác</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><div class="entity"><EntityAvatar :src="row.logo_url" :name="row.name" :size="40"/><div><div class="entity-name">{{ row.name }}</div><div class="entity-sub">{{ row.code }} · {{ row.short_name }}</div></div></div></td><td><StatusBadge :status="row.registration_status"/></td><td>{{ row.player_count }}</td><td><b>{{ money(row.balance,true) }}</b></td><td><div>{{ row.username||'Chưa tạo' }}</div><small class="muted">{{ row.account_active?'Đang hoạt động':'Đang khóa' }}</small></td><td><div class="row-actions"><button v-if="row.registration_status==='PENDING'" class="btn btn-sm btn-success" @click="approve(row,'APPROVED')"><Check :size="14"/>Duyệt</button><button v-if="row.registration_status==='PENDING'" class="btn btn-sm btn-danger" @click="approve(row,'REJECTED')"><X :size="14"/>Từ chối</button><button class="btn btn-sm" @click="openAccount(row)"><KeyRound :size="14"/>Tài khoản</button></div></td></tr></tbody></table></div><PaginationBar v-bind="meta" @change="load"/></div><BaseModal :open="modal==='club'" title="Tạo câu lạc bộ" @close="modal=''" width="720px"><form class="form-grid" @submit.prevent="saveClub"><label><span class="label">Mã CLB</span><input v-model="form.code" class="input" required/></label><label><span class="label">Tên viết tắt</span><input v-model="form.short_name" class="input" required/></label><label class="form-group full"><span class="label">Tên đầy đủ</span><input v-model="form.name" class="input" required/></label><label class="form-group full"><span class="label">URL logo</span><input v-model="form.logo_url" class="input"/></label><label><span class="label">Trạng thái</span><select v-model="form.registration_status" class="select"><option value="APPROVED">Đã duyệt</option><option value="PENDING">Chờ duyệt</option></select></label><label><span class="label">Hoạt động</span><select v-model="form.is_active" class="select"><option :value="true">Có</option><option :value="false">Không</option></select></label><div class="form-group full actions"><button class="btn" type="button" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">{{ busy?'Đang lưu...':'Tạo CLB' }}</button></div></form></BaseModal><BaseModal :open="modal==='account'" title="Tài khoản chung của CLB" @close="modal=''" width="520px"><form class="form-grid" @submit.prevent="saveAccount"><label class="form-group full"><span class="label">Tên đăng nhập</span><input v-model="form.username" class="input" required/></label><label class="form-group full"><span class="label">Mật khẩu mới (để trống nếu không đổi)</span><input v-model="form.password" type="password" class="input"/></label><label class="form-group full"><span class="label">Trạng thái tài khoản</span><select v-model="form.is_active" class="select"><option :value="true">Hoạt động</option><option :value="false">Khóa</option></select></label><div class="form-group full actions"><button class="btn" type="button" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">Lưu tài khoản</button></div></form></BaseModal></div></template>
<style scoped>.toolbar{margin-bottom:18px;padding:13px}.search{display:flex;align-items:center;gap:8px;min-width:300px}.search .input{border:0;background:transparent;box-shadow:none}.toolbar-actions .select{width:190px}.table-card{padding:0;overflow:hidden}.row-actions,.actions{display:flex;gap:7px;justify-content:flex-end;flex-wrap:wrap}@media(max-width:650px){.search{min-width:100%}.toolbar-actions .select{width:100%}}</style>
